<?php
declare(strict_types=1);
require dirname(__DIR__) . '/vendor/autoload.php';
use app\service\Community;
use app\model\CommunityBoard;
use app\model\CommunityPost;
use app\model\CommunityComment;
use app\model\CommunityMember;
use app\model\CommunityLike;
use app\model\User;
use app\model\UserDevice;
use think\exception\HttpException;
use think\facade\Db;
use think\Request;

$app = new think\App(dirname(__DIR__));
$app->initialize();
$config = config('database.connections.mysql');
if (!in_array($config['hostname'], ['127.0.0.1', 'localhost', '::1'], true)) throw new RuntimeException('Community fixture requires loopback DB');
if (count(Db::query("SHOW TABLES LIKE 'community%'") ) !== 9) throw new RuntimeException('Community schema missing');
echo 'DB ' . $config['hostname'] . ':' . $config['hostport'] . '/' . $config['database'] . '; rollback fixture' . PHP_EOL;
$failures = []; $checks = 0;
$assert = function (bool $ok, string $case) use (&$failures, &$checks) { $checks++; if (!$ok) $failures[] = $case; };
$throws = function (callable $fn, int $code, string $case) use ($assert) { try { $fn(); $assert(false, $case . ': expected ' . $code); } catch (HttpException $e) { $assert($e->getStatusCode() === $code, $case . ': got ' . $e->getStatusCode()); } };
$fixtureTables = ['community', 'community_post', 'community_comment', 'community_member', 'community_like', 'user', 'user_device', 'team', 'team_member', 'team_customer', 'entity', 'entity_session', 'file'];
$before = [];
foreach ($fixtureTables as $table) $before[$table] = Db::name($table)->count();
$uploadFixture = null;
Db::startTrans();
try {
    $suffix = bin2hex(random_bytes(5));
    $makeUser = function (string $label) use ($suffix) {
        $user = User::create(['phone' => '19' . random_int(100000000, 999999999), 'username' => 'community-' . $label . '-' . $suffix, 'password' => 'community-test']);
        $device = bin2hex(random_bytes(32));
        UserDevice::create(['user_id' => $user->id, 'device_token' => $device, 'device_type' => 'web', 'last_active_time' => time()]);
        return [$user, $device, app(\app\service\Jwt::class)->createToken((int) $user->id, $device)];
    };
    [$owner, $device, $baseToken] = $makeUser('owner');
    [$externalOwner, $externalDevice, $externalBase] = $makeUser('external');
    [$admin, $adminDevice, $adminToken] = $makeUser('admin');
    $teamData = app(\app\service\Team::class)->create((int) $owner->id, 'community-a-' . $suffix, 'Community A');
    $externalData = app(\app\service\Team::class)->create((int) $externalOwner->id, 'community-b-' . $suffix, 'Community B');
    $teamId = $teamData['id']; $externalId = $externalData['id'];
    $team = \app\model\Team::find($teamId);
    $externalTeam = \app\model\Team::find($externalId);
    $entity = \app\model\TeamMember::where('team_id', $teamId)->where('user_id', $owner->id)->find()->identity;
    $external = \app\model\TeamMember::where('team_id', $externalId)->where('user_id', $externalOwner->id)->find()->identity;
    $actor = app(\app\service\Entity::class)->subject((int) $entity->id);
    $externalActor = app(\app\service\Entity::class)->subject((int) $external->id);
    $token = app(\app\service\IdentitySession::class)->receive((int) $owner->id, $device, $entity->slug)['token'];
    $externalToken = app(\app\service\IdentitySession::class)->receive((int) $externalOwner->id, $externalDevice, $external->slug)['token'];
    $service = app(Community::class);
    $community = $service->save(null, $teamId, ['slug' => 'test-a-' . $suffix, 'name' => 'A', 'description' => 'public']);
    $other = $service->save(null, $externalId, ['slug' => 'test-b-' . $suffix, 'name' => 'B']);
    $platform = $service->save(null, null, ['slug' => 'test-platform-' . $suffix, 'name' => 'Platform', 'is_official' => true]);
    $board = CommunityBoard::where('community_id', $community->id)->find();
    $otherBoard = CommunityBoard::where('community_id', $other->id)->find();
    $assert($board && $board->enabled, 'new community has default board');
    $assert($platform->is_official && $platform->team_id === null, 'official platform ownership');
    $assert($service->canManage($community, $actor), 'target owner team Permission grants management without membership');
    $ownerData = $service->data($community, null);
    $ownerDataAgain = $service->data($community, null);
    $assert($ownerDataAgain['owner']['name'] === 'Community A' && !isset($ownerDataAgain['team']), 'public owner DTO includes name and never expands private Team model');
    $assert(!$service->canManage($community, $externalActor), 'another team owner does not manage community');
    $throws(fn () => $service->scope($community, null), 404, 'Admin cannot manage team community');
    $throws(fn () => $service->scope($platform, $teamId), 404, 'Team cannot manage platform community');
    $throws(fn () => $service->scope($other, $teamId), 404, 'Team cannot manage another team community');
    $throws(fn () => $service->actor(null, 0), 428, 'missing Entity uses recovery error');
    $throws(fn () => $service->actor($actor, (int) $external->id), 409, 'stale identity rejected');
    $postBody = ['board_id' => (int) $board->id, 'title' => 'Hello', 'content' => 'Public body'];
    $throws(fn () => $service->writeContent($community, $externalActor, 'post', 0, 0, $postBody), 403, 'membership required');
    $service->relation($community, $externalActor, 'join', true);
    $service->relation($community, $externalActor, 'join', true);
    $assert(CommunityMember::where('community_id', $community->id)->where('entity_id', $external->id)->count() === 1, 'duplicate join is unique');
    $throws(fn () => $service->writeContent($community, $externalActor, 'post', 0, 0, array_replace($postBody, ['board_id' => $otherBoard->id])), 404, 'foreign board rejected');
    $post = $service->writeContent($community, $externalActor, 'post', 0, 0, $postBody);
    $comment = $service->writeContent($community, $externalActor, 'comment', 0, $post['id'], ['content' => 'Reply']);
    $assert($post['author_entity_id'] === (int) $external->id, 'cross-team author stays current Entity');
    $throws(fn () => $service->writeContent($community, $actor, 'post', $post['id'], 0, $postBody), 403, 'manager cannot rewrite author');
    $throws(fn () => $service->visiblePost($other, $post['id'], null), 404, 'cross-community post rejected');
    $service->relation($community, $externalActor, 'like', true, $post['id']);
    $service->relation($community, $externalActor, 'like', true, $post['id']);
    $assert(CommunityLike::where('post_id', $post['id'])->count() === 1, 'duplicate like is unique');
    $service->mute($community, (int) $external->id, true, 'Flooding');
    $throws(fn () => $service->writeContent($community, $externalActor, 'comment', 0, $post['id'], ['content' => 'Muted']), 403, 'mute prevents comment');
    $service->relation($community, $externalActor, 'join', false);
    $mutedMember = $service->resources($community, 'members', $actor, true, 0, 0, '', 1, 20)['list'][0];
    $assert(!$mutedMember['joined'] && $mutedMember['muted'] && $mutedMember['entity_id'] === (int) $external->id, 'departed muted Entity stays discoverable');
    $service->relation($community, $externalActor, 'join', true);
    $assert($service->data($community, $externalActor)['is_muted'], 'leave/rejoin preserves mute');
    $service->administrator($community, $external->slug, 0, false);
    $assert($service->canManage($community, $externalActor), 'cross-team muted Entity may manage');
    $service->administrator($community, '', (int) $external->id, true);
    $assert(!$service->canManage($community, $externalActor), 'removal takes effect immediately');
    $service->mute($community, (int) $external->id, false, '');
    $service->mute($community, (int) $external->id, true, 'Inactive test');
    $externalMember = \app\model\TeamMember::find($external->entityable_id);
    $externalMember->save(['status' => \app\enum\TeamMemberStatus::Blocked]);
    $service->mute($community, (int) $external->id, false, '');
    $assert(!\app\model\CommunityMute::where('community_id', $community->id)->where('entity_id', $external->id)->find(), 'inactive Entity can be unmuted');
    $externalMember->save(['status' => \app\enum\TeamMemberStatus::Active]);
    $service->moderate($community, 'post', $post['id'], true, false, 'Unsafe');
    $service->moderate($community, 'post', $post['id'], null, true, '');
    $assert(CommunityPost::find($post['id'])->status === 'Hidden' && CommunityPost::find($post['id'])->hidden_reason === 'Unsafe', 'pin-only moderation retains visibility and reason');
    $service->moderate($community, 'post', $post['id'], false, null, '');
    $assert(CommunityPost::find($post['id'])->pinned, 'visibility-only moderation retains pin');
    $service->moderate($community, 'post', $post['id'], true, false, 'Unsafe');
    $throws(fn () => $service->visiblePost($community, $post['id'], null), 404, 'hidden post detail denied');
    $assert($service->resources($community, 'posts', $externalActor, false, 0, 0, '', 1, 20)['total'] === 0, 'hidden post absent even from author public feed');
    $assert($service->contentData($service->visiblePost($community, $post['id'], $externalActor), $externalActor)['content'] === '', 'author hidden detail only exposes reason');
    $throws(fn () => $service->resources($community, 'comments', $externalActor, false, $post['id'], 0, '', 1, 20), 404, 'hidden parent comments cannot leak');
    $assert($service->resources($community, 'posts', $actor, true, 0, 0, '', 1, 20)['list'][0]['content'] === 'Public body', 'manager can inspect hidden body');
    $service->moderate($community, 'post', $post['id'], false, true, '');
    $service->writeContent($community, $externalActor, 'post', 0, 0, ['board_id' => (int) $board->id, 'title' => 'Later', 'content' => 'Later body']);
    $assert($service->resources($community, 'posts', null, false, 0, 0, '', 1, 20)['list'][0]['id'] === $post['id'], 'pinned post precedes later posts');
    $service->moderate($community, 'comment', $comment['id'], true, false, 'Unsafe reply');
    $assert($service->resources($community, 'comments', null, false, $post['id'], 0, '', 1, 20)['total'] === 0, 'hidden comments absent publicly');
    $service->moderate($community, 'comment', $comment['id'], false, false, '');
    $service->saveBoard($community, (int) $board->id, ['name' => 'Disabled', 'sort' => 0, 'enabled' => false]);
    $throws(fn () => $service->writeContent($community, $externalActor, 'post', 0, 0, $postBody), 403, 'disabled board blocks new post');
    $assert($service->visiblePost($community, $post['id'], null)->id === $post['id'], 'disabled board retains existing post');
    $throws(fn () => $service->save($community, $teamId, ['status' => 'Paused']), 422, 'pause requires reason');
    $community = $service->save($community, $teamId, ['status' => 'Paused', 'reason' => 'Maintenance']);
    $throws(fn () => $service->relation($community, $actor, 'join', true), 403, 'pause blocks joining');
    $throws(fn () => $service->relation($community, $externalActor, 'like', true, $post['id']), 403, 'pause blocks liking');
    $assert($service->visiblePost($community, $post['id'], null)->id === $post['id'], 'pause preserves reads');
    $community = $service->save($community, $teamId, ['status' => 'Active']);
    $service->writeContent($community, $externalActor, 'post', $post['id'], 0, [], true);
    $assert($service->contentData($service->visiblePost($community, $post['id'], null), null)['status'] === 'Deleted', 'author deletion keeps placeholder');
    $throws(fn () => $service->moderate($community, 'post', $post['id'], false, false, ''), 409, 'moderation never resurrects author deletion');
    $team->save(['is_banned' => 1]);
    $throws(fn () => $service->relation($community, $externalActor, 'join', true), 403, 'inactive owner team blocks interactions');
    $throws(fn () => $service->save(null, $teamId, ['slug' => 'blocked-' . $suffix, 'name' => 'Blocked']), 403, 'inactive team cannot create');
    $assert($service->resolve((int) $community->id)->id === $community->id, 'inactive team retains public read');
    $team->save(['is_banned' => 0]);

    // Attachments belong to the author team, never the community owner.
    $domain = rtrim((string) config('aliyun.oss_domain'), '/');
    if ($domain === '') $domain = 'https://' . config('aliyun.bucket') . '.oss-' . config('aliyun.region') . '.aliyuncs.com';
    $makeFile = function (int $id, int $entityId) use ($suffix) {
        return \app\model\File::create(['team_id' => $id, 'entity_id' => $entityId, 'hash' => bin2hex(random_bytes(32)), 'name' => 'community.png', 'path' => 'community-fixture/' . $suffix . '/' . bin2hex(random_bytes(8)) . '.png', 'size' => 10, 'mime_type' => 'image/png', 'source' => \app\enum\FileSource::Attachment, 'pending_until' => time() + 3600]);
    };
    $file = $makeFile($externalId, (int) $external->id);
    $service->saveBoard($community, (int) $board->id, ['name' => 'Discussion', 'sort' => 0, 'enabled' => true]);
    $attachmentPost = $service->writeContent($community, $externalActor, 'post', 0, 0, ['board_id' => (int) $board->id, 'title' => 'Attachment', 'content' => '![](' . $domain . '/' . $file->path . ') [person](lostsky://entity/' . $entity->slug . ')']);
    $assert(\app\model\File::find($file->id)->pending_until === null, 'cross-team author attachment activates in author team');
    $assert(\app\model\MarkdownReference::where('referenceable_type', 'communityPost')->where('referenceable_id', $attachmentPost['id'])->count() === 1, 'Community Markdown Entity reference is tracked');
    $foreignFile = $makeFile($teamId, (int) $entity->id);
    $throws(fn () => $service->writeContent($community, $externalActor, 'post', 0, 0, ['board_id' => (int) $board->id, 'title' => 'Foreign attachment', 'content' => '![](' . $domain . '/' . $foreignFile->path . ')']), 422, 'author cannot claim owner team attachment');
    $assert(\app\model\File::find($foreignFile->id)->pending_until !== null, 'rejected attachment remains pending');
    $noticeFile = $makeFile($externalId, (int) $external->id);
    $noticeBody = '![](' . $domain . '/' . $noticeFile->path . ')';
    $notice = $service->saveAnnouncement($platform, 0, ['title' => 'Attachment notice', 'content' => $noticeBody, 'pinned' => true], $externalActor);
    $assert(\app\model\File::find($noticeFile->id)->pending_until === null && $notice['attachment_team_id'] === $externalId, 'announcement uses publishing Entity attachment team');
    $service->saveAnnouncement($platform, $notice['id'], ['title' => 'Admin edit', 'content' => $noticeBody . ' changed', 'pinned' => false], null);
    $service->saveAnnouncement($platform, $notice['id'], ['title' => 'Other team manager edit', 'content' => $noticeBody . ' edited by another team', 'pinned' => true], $actor);
    $assert(\app\model\File::find($noticeFile->id)->pending_until === null, 'cross-team governor can retain previously activated announcement attachment');
    $mixedFile = $makeFile($teamId, (int) $entity->id);
    $service->saveAnnouncement($platform, $notice['id'], ['title' => 'Mixed provenance', 'content' => $noticeBody . ' ![](' . $domain . '/' . $mixedFile->path . ')', 'pinned' => true], $actor);
    $assert(\app\model\File::find($mixedFile->id)->pending_until === null, 'cross-team governor can activate own new attachment while retaining old attachment');
    $commentFile = $makeFile($externalId, (int) $external->id);
    $attachmentComment = $service->writeContent($community, $externalActor, 'comment', 0, $attachmentPost['id'], ['content' => '![](' . $domain . '/' . $commentFile->path . ')']);
    $assert(\app\model\File::find($commentFile->id)->pending_until === null, 'comment rendered attachment activates');
    $service->moderate($community, 'comment', $attachmentComment['id'], true, false, 'Hidden attachment');
    $assert(CommunityComment::find($attachmentComment['id'])->content !== '' && \app\model\File::find($commentFile->id)->pending_until === null, 'hidden comment retains body and activation for restore');
    $throws(fn () => $service->saveAnnouncement($platform, 0, ['title' => 'Admin claim', 'content' => $noticeBody, 'pinned' => true], null), 422, 'base Admin cannot create internal attachment reference');
    $service->writeContent($community, $externalActor, 'post', $attachmentPost['id'], 0, [], true);
    $assert(CommunityPost::find($attachmentPost['id'])->content === '' && \app\model\MarkdownReference::where('referenceable_type', 'communityPost')->where('referenceable_id', $attachmentPost['id'])->count() === 0, 'author deletion clears Markdown content and Entity references');

    // Dispatch the actual app routes and run their controller middleware pipeline.
    $dispatch = function (string $application, string $method, string $path, string $bearer = '', array $body = [], ?int $targetTeam = null, array $files = []) use ($app): array {
        $app->setNamespace('app\\' . $application);
        $app->http->name($application);
        $route = new think\Route($app);
        $app->instance('route', $route);
        $app->instance('middleware', new think\Middleware($app));
        $request = (new Request)->setMethod($method)->setPathinfo($path)->setUrl('/' . $path)->withPost($body)->withFiles($files)->withHeader($bearer ? ['Authorization' => 'Bearer ' . $bearer] : []);
        if ($targetTeam) { $request->team_id = $targetTeam; $request->team = \app\model\Team::find($targetTeam); $request->slug = $request->team->slug; }
        $app->instance('request', $request);
        require dirname(__DIR__) . '/app/' . $application . '/route/app.php';
        $response = $route->dispatch($request);
        if ($response->getCode() >= 400) throw new HttpException($response->getCode(), $response->getData()['message'] ?? 'Route denied');
        return $response->getData();
    };
    $public = $dispatch('community', 'GET', 'communities/' . $community->slug);
    $assert($public['data']['slug'] === $community->slug && !$public['data']['is_joined'], 'anonymous actual route publicly reads');
    $basic = $dispatch('community', 'GET', 'communities/' . $community->slug, $baseToken);
    $assert($basic['data']['entity_id'] === null, 'base user can publicly read without Entity');
    $throws(fn () => $dispatch('community', 'POST', 'communities/' . $community->slug . '/join', $baseToken), 428, 'base-user actual route write requires Entity');
    $throws(fn () => $dispatch('community', 'POST', 'communities/' . $community->slug . '/join'), 401, 'anonymous actual route write requires login');
    $throws(fn () => $dispatch('community', 'POST', 'communities/' . $community->slug . '/join', $token, ['expected_entity_id' => $external->id]), 409, 'actual route rejects stale identity');
    $throws(fn () => $dispatch('community', 'POST', 'communities/' . $community->slug . '/manage/administrators', $token, ['expected_entity_id' => $entity->id, 'entity_slug' => $external->slug]), 404, 'Community never exposes administrator appointment');

    // Account root identities must reach Community without any role in its owner team.
    [$participant, $participantDevice, $participantBase] = $makeUser('participant');
    $participantTeam = app(\app\service\Team::class)->create((int) $participant->id, 'community-c-' . $suffix, 'Participant team');
    $participantMember = \app\model\TeamMember::where('team_id', $participantTeam['id'])->where('user_id', $participant->id)->find()->identity;
    $customer = \app\model\TeamCustomer::create(['team_id' => $participantTeam['id'], 'user_id' => $participant->id, 'is_blocked' => 0]);
    $customerEntity = app(\app\service\Entity::class)->claimCustomer((int) $customer->id, 'community-customer-' . $suffix);
    $candidateData = $dispatch('account', 'GET', 'identity/candidates', $participantBase)['data'];
    $candidateSlugs = array_column($candidateData, 'slug');
    $assert(in_array($participantMember->slug, $candidateSlugs, true) && in_array($customerEntity->slug, $candidateSlugs, true), 'actual Account candidates include own member and customer roots');
    $assert(!\app\model\TeamEntityRole::where('team_id', $teamId)->whereIn('entity_id', [$participantMember->id, $customerEntity->id])->count(), 'participants have no role in community owner team');
    $availability = app(\app\service\File::class)->uploadAvailability($participantTeam['id']);
    $assert($availability['available'] && $availability['size_limit'] === (int) config('file.tiers.0.size'), 'team without paid file ability has base upload capacity');
    $uploadFixture = tempnam(sys_get_temp_dir(), 'community-image-');
    file_put_contents($uploadFixture, base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/l9sAAAAASUVORK5CYII='));
    $uploadFile = ['name' => 'community.png', 'type' => 'image/png', 'tmp_name' => $uploadFixture, 'error' => UPLOAD_ERR_OK, 'size' => filesize($uploadFixture)];
    // A pending object fixture exercises validation/deduplication without writing to OSS.
    $pendingImage = $makeFile($participantTeam['id'], (int) $participantMember->id);
    Db::name('file')->where('id', $pendingImage->id)->update(['hash' => hash_file('sha256', $uploadFixture), 'size' => filesize($uploadFixture)]);
    if (Db::name('file')->where('team_id', $participantTeam['id'])->where('hash', hash_file('sha256', $uploadFixture))->value('id') !== (int) $pendingImage->id) throw new RuntimeException('Pending upload deduplication fixture missing');
    foreach ([$participantMember, $customerEntity] as $participantEntity) {
        $kind = (string) $participantEntity->entityable_type;
        $issued = $dispatch('account', 'POST', 'identity/receive', $participantBase, ['slug' => $participantEntity->slug])['data'];
        $participantToken = $issued['token'];
        $assert($issued['identity']['type'] === $kind, $kind . ': actual Account receives chosen root');
        $session = $dispatch('community', 'GET', 'session', $participantToken)['data'];
        $assert($session['entity']['id'] === (int) $participantEntity->id && $session['upload_team_slug'] === $participantTeam['slug'], $kind . ': Community session keeps global actor and own upload team');
        $expected = ['expected_entity_id' => (int) $participantEntity->id];
        Db::name('file')->where('id', $pendingImage->id)->update(['pending_until' => time() + 3600]);
        $throws(fn () => $dispatch('community', 'POST', 'upload', $participantToken, ['expected_entity_id' => $entity->id], null, ['file' => $uploadFile]), 409, $kind . ': image upload rejects stale identity before touching files');
        $upload = $dispatch('community', 'POST', 'upload', $participantToken, $expected, null, ['file' => $uploadFile])['data'];
        $assert($upload['id'] === (int) $pendingImage->id, $kind . ': actual Community upload accepts image without owner-team role');
        foreach ([$community, $platform] as $destination) {
            $prefix = 'communities/' . $destination->slug;
            $destinationBoard = CommunityBoard::where('community_id', $destination->id)->find();
            $dispatch('community', 'POST', $prefix . '/join', $participantToken, $expected);
            $joined = $dispatch('community', 'GET', $prefix, $participantToken)['data'];
            $assert($joined['is_joined'] && !$joined['can_manage'], $kind . ': joins ' . $destination->owner_type . ' without governance permission');
            $mine = $dispatch('community', 'GET', 'mine', $participantToken)['data'];
            $assert(in_array((int) $destination->id, array_column($mine['list'], 'id'), true), $kind . ': joined community appears in mine');
            $textPost = $dispatch('community', 'POST', $prefix . '/posts', $participantToken, $expected + ['board_id' => (int) $destinationBoard->id, 'title' => $kind . ' text', 'content' => 'Text from current global Entity'])['data'];
            $assert($textPost['author_entity_id'] === (int) $participantEntity->id, $kind . ': actual text post keeps author in cross-team/platform community');
            $imagePost = $dispatch('community', 'POST', $prefix . '/posts', $participantToken, $expected + ['board_id' => (int) $destinationBoard->id, 'title' => $kind . ' image', 'content' => '![](' . $upload['url'] . ')'])['data'];
            $assert($imagePost['author_entity_id'] === (int) $participantEntity->id && \app\model\File::find($pendingImage->id)->pending_until === null, $kind . ': actual image post activates own-team attachment');
            $reply = $dispatch('community', 'POST', $prefix . '/posts/' . $textPost['id'] . '/comments', $participantToken, $expected + ['content' => 'Reply from current Entity'])['data'];
            $assert($reply['author_entity_id'] === (int) $participantEntity->id, $kind . ': actual comment keeps author');
            $dispatch('community', 'POST', $prefix . '/posts/' . $textPost['id'] . '/like', $participantToken, $expected + ['liked' => true]);
            $assert(CommunityLike::where('post_id', $textPost['id'])->where('entity_id', $participantEntity->id)->count() === 1, $kind . ': actual like belongs to current Entity');
            $dispatch('community', 'POST', $prefix . '/leave', $participantToken, $expected);
            $assert(!CommunityMember::where('community_id', $destination->id)->where('entity_id', $participantEntity->id)->find(), $kind . ': actual leave removes only membership');
        }
        $participantBase = $dispatch('account', 'POST', 'identity/drop', $participantToken)['data']['token'];
        $assert($dispatch('community', 'GET', 'session', $participantBase)['data']['entity'] === null, $kind . ': actual Account drop returns Community to base user');
        $throws(fn () => $dispatch('community', 'GET', 'session', $participantToken), 401, $kind . ': dropped Entity token immediately invalid');
        $rootSlugs = array_column($dispatch('account', 'GET', 'identity/candidates', $participantBase)['data'], 'slug');
        $assert(in_array($customerEntity->slug, $rootSlugs, true) && in_array($participantMember->slug, $rootSlugs, true), $kind . ': drop restores both root choices for switching');
    }
    $readRole = \app\model\PlatformAdminRole::create(['role_key' => 'community-read-' . $suffix, 'name' => 'Read', 'description' => '', 'is_system' => 0]);
    \app\model\PlatformAdminUserRole::create(['user_id' => $admin->id, 'role_id' => $readRole->id, 'assigned_by_user_id' => null]);
    $permission = \app\model\PlatformAdminRolePermission::create(['role_id' => $readRole->id, 'permission_key' => 'admin.community.read']);
    $read = $dispatch('admin', 'GET', 'communities/' . $platform->id, $adminToken);
    $assert(!$read['data']['can_write'] && !$read['data']['can_moderate'], 'read-only Admin has separate capabilities');
    $throws(fn () => $dispatch('admin', 'POST', 'communities/' . $platform->id, $adminToken, ['name' => 'Forbidden']), 403, 'read-only Admin lacks write');
    $writePermission = \app\model\PlatformAdminRolePermission::create(['role_id' => $readRole->id, 'permission_key' => 'admin.community.write']);
    $dispatch('admin', 'POST', 'communities/' . $platform->id, $adminToken, ['name' => 'Platform Updated']);
    $assert($service->resolve((int) $platform->id)->name === 'Platform Updated', 'Admin user without Entity updates platform metadata');
    $throws(fn () => $dispatch('admin', 'POST', 'communities/' . $platform->id . '/boards/0', $adminToken, ['name' => 'Forbidden']), 403, 'write permission does not grant moderation');
    $writePermission->force()->delete();
    \app\model\PlatformAdminRolePermission::create(['role_id' => $readRole->id, 'permission_key' => 'admin.community.moderate']);
    $announcement = $dispatch('admin', 'POST', 'communities/' . $platform->id . '/announcements/0', $adminToken, ['title' => 'Official', 'content' => 'Notice', 'pinned' => true]);
    $throws(fn () => $dispatch('admin', 'POST', 'communities/' . $platform->id . '/boards/not-a-number', $adminToken, ['name' => 'Invalid route']), 404, 'non-numeric board route cannot coerce into create id zero');
    $assert($announcement['data']['content'] === 'Notice' && $announcement['data']['attachment_team_id'] === null, 'Admin base user publishes announcement without forged Entity');
    $throws(fn () => $dispatch('admin', 'POST', 'communities/' . $platform->id . '/administrators', $adminToken, ['entity_slug' => $external->slug]), 403, 'moderate permission cannot appoint administrator');
    $throws(fn () => $dispatch('admin', 'GET', 'communities/' . $community->id, $adminToken), 404, 'Admin actual route refuses team ownership');
    $throws(fn () => $dispatch('admin', 'POST', 'communities/' . $platform->id . '/boards/' . $board->id, $adminToken, ['name' => 'Other']), 404, 'Admin actual route refuses cross-community child');
    $throws(fn () => $dispatch('team', 'GET', 'communities/' . $platform->id, $token, [], $teamId), 404, 'Team actual route refuses platform ownership');
    $throws(fn () => $dispatch('team', 'GET', 'communities/' . $other->id, $token, [], $teamId), 404, 'Team actual route refuses another owner team');
    $teamRead = $dispatch('team', 'GET', 'communities/' . $community->id, $token, [], $teamId);
    $assert($teamRead['data']['can_manage'], 'Team actual route allows target team manager');
    $dispatch('team', 'POST', 'communities/' . $community->id . '/boards/0', $token, ['name' => 'Team-managed', 'sort' => 1, 'enabled' => true, 'expected_entity_id' => $entity->id], $teamId);
    $teamEvent = \app\model\BusinessAuditEvent::where('resource_id', $community->id)->where('action', 'community.board.save')->where('application', 'team')->find();
    $assert($teamEvent && $teamEvent->team_id === $teamId && $teamEvent->entity_id === (int) $entity->id && $teamEvent->authenticated_user_id === (int) $owner->id, 'Team audit carries target team and real Entity/user');
    $service->administrator($platform, $external->slug, 0, false);
    $manageRead = $dispatch('community', 'GET', 'communities/' . $platform->slug . '/manage/boards', $externalToken);
    $assert($manageRead['data']['total'] === 1, 'cross-team appointed Entity gets Community actual governance route');
    $dispatch('community', 'POST', 'communities/' . $platform->slug . '/manage/boards/0', $externalToken, ['name' => 'Entity managed', 'sort' => 1, 'enabled' => true, 'expected_entity_id' => $external->id]);
    $communityEvent = \app\model\BusinessAuditEvent::where('resource_id', $platform->id)->where('action', 'community.board.save')->where('application', 'community')->find();
    $assert($communityEvent && $communityEvent->team_id === null && $communityEvent->entity_id === (int) $external->id && $communityEvent->authenticated_user_id === (int) $externalOwner->id, 'Community audit carries Entity/user without forged owner team');
    $service->administrator($platform, '', (int) $external->id, true);
    $throws(fn () => $dispatch('community', 'GET', 'communities/' . $platform->slug . '/manage/boards', $externalToken), 403, 'Community route immediately denies removed administrator');
    $event = \app\model\BusinessAuditEvent::where('resource_id', $platform->id)->where('action', 'community.announcement.save')->find();
    $assert($event && $event->entity_id === null && $event->team_id === null && $event->authenticated_user_id === (int) $admin->id && $event->context['community_id'] === (int) $platform->id, 'platform audit identifies real user and community');
    $permission->force()->delete();
    $throws(fn () => $dispatch('admin', 'POST', 'communities/' . $platform->id . '/boards/0', $adminToken, ['name' => 'Missing read']), 403, 'moderation permission alone cannot bypass Admin read requirement');
    $role = \app\model\TeamRole::create(['team_id' => $teamId, 'role_key' => 'community-external', 'name' => 'External governor', 'description' => '', 'sort' => 0]);
    $binding = \app\model\TeamEntityRole::create(['team_id' => $teamId, 'entity_id' => $external->id, 'role_id' => $role->id]);
    foreach (['community.team.read', 'community.team.manage'] as $key) \app\model\TeamRolePermission::create(['team_id' => $teamId, 'role_id' => $role->id, 'permission_key' => $key]);
    $assert($service->canManage($community, $externalActor), 'target-team granted external Entity has management without administrator relation');
    $externalTeamRead = $dispatch('team', 'GET', 'communities/' . $community->id, $externalToken, [], $teamId);
    $assert($externalTeamRead['data']['entity_id'] === (int) $external->id && $externalTeamRead['data']['can_manage'], 'Team external manager keeps actual source Entity');
    $binding->force()->delete();
    $assert(!$service->canManage($community, $externalActor), 'revoked target-team role immediately removes owner management');
    $service->administrator($platform, $external->slug, 0, false);
    $externalMember->save(['status' => \app\enum\TeamMemberStatus::Blocked]);
    $assert(!$service->canManage($platform, $externalActor), 'invalid Entity administrator never retains management');
    $throws(fn () => $dispatch('community', 'GET', 'communities/' . $platform->slug . '/manage/boards', $externalToken), 401, 'actual route rejects invalid Entity session');
} catch (Throwable $e) {
    $failures[] = get_class($e) . ': ' . $e->getMessage() . ' at ' . $e->getFile() . ':' . $e->getLine();
} finally {
    Db::rollback();
    if ($uploadFixture !== null) unlink($uploadFixture);
}
foreach ($before as $table => $count) $assert(Db::name($table)->count() === $count, 'fixture rollback leaves no ' . $table . ' records');
if ($failures) { fwrite(STDERR, implode(PHP_EOL, $failures) . PHP_EOL); exit(1); }
echo 'Community behavior and route tests passed: ' . $checks . ' assertions' . PHP_EOL;
